select pg_temp.assert(:'dsa_wrong_code'::boolean and :'dsa_wrong_case'::boolean and :'dsa_lower_case'::boolean,
  'DSA41-10d zły kod i obcy numer → brak wyniku (ta sama odpowiedź)');

