select pg_temp.un45_sql($q$
  insert into auth.users(id,email,name,raw_user_meta_data) values
    ('e0450000-0000-0000-0000-0000000000f1','cmp1@test.be','Cm P1','{"role":"candidate","first_name":"Cm","last_name":"P1","locale":"pl"}'),
