-- LOC194. Słownik miejscowości z aliasami (#194, 0112): gminy Belgii + lista kanoniczna,
--         aliasy PL/NL/FR/EN po kluczu cityKey, odczyt publiczny, zapis tylko serwisowy.
-- ============================================================================
reset role; reset app.current_uid;
select pg_temp.assert(
  (select count(*) from public.locations where kind = 'municipality' and is_demo = false) >= 560
  and (select count(*) from public.locations where kind = 'former_municipality') >= 20,
  'LOC194-1 gminy obecne i zniesione przy fuzjach w słowniku');
select pg_temp.assert(not exists (
    select 1 from public.locations l
     where l.country = 'BE' and l.latitude is not null
       and not exists (select 1 from public.location_aliases a where a.location_id = l.id)),
  'LOC194-2 każda miejscowość ma alias');
select pg_temp.assert(
  (select (name, latitude, longitude, sort_order) = ('Brussels', 50.850300, 4.351700, 10)
     from public.locations where slug = 'brussels')
  and (select (name, latitude, longitude, sort_order) = ('Liège', 50.632600, 5.579700, 70)
     from public.locations where slug = 'liege'),
  'LOC194-3 wiersze 0010 bez zmian');

-- Zapytanie loadera (src/lib/data/matching.ts) pod rolą klienta i RLS.
set role authenticated; set app.current_uid = :'CANDA'; select pg_temp.assert_client_role();
select pg_temp.assert(
  (select array_agg(format('%s:%s,%s', a.alias_key, l.latitude, l.longitude) order by a.alias_key)
     from public.location_aliases a join public.locations l on l.id = a.location_id
    where l.is_active = true and a.alias_key = any(array['antwerpia', 'luik', 'atlantyda']))
  = array['antwerpia:51.219400,4.402500', 'luik:50.632600,5.579700'],
  'LOC194-4 alias PL/NL → współrzędne, nieznane miasto bez wiersza');
select pg_temp.assert(
  (select location_id from public.location_aliases where alias_key = 'elsene')
  = (select location_id from public.location_aliases where alias_key = 'ixelles'),
  'LOC194-5 nazwy NL/FR gminy spoza listy w kodzie wskazują ten sam wiersz');
select pg_temp.expect_error(
  'insert into public.location_aliases (location_id, alias, alias_key) select id, ''X'', ''x-loc194'' from public.locations limit 1',
  'permission denied', 'LOC194-6 zalogowany nie dodaje aliasu');
select pg_temp.expect_error('update public.location_aliases set alias = alias',
  'permission denied', 'LOC194-6b zalogowany nie zmienia aliasu');
select pg_temp.expect_error('update public.locations set latitude = 0',
  'permission denied', 'LOC194-6c zalogowany nie zmienia współrzędnych');
reset role; reset app.current_uid;
set role anon; select pg_temp.assert_client_role();
select pg_temp.assert((select count(*) from public.location_aliases where alias_key = 'bruksela') = 1,
  'LOC194-7 anon czyta aliasy');
select pg_temp.expect_error('delete from public.location_aliases',
  'permission denied', 'LOC194-7b anon nie usuwa aliasów');
reset role;

-- Integralność: jeden klucz = jedna miejscowość, klucz w postaci cityKey, NIS unikalny.
select pg_temp.expect_error(
  'insert into public.location_aliases (location_id, alias, alias_key) select id, ''Antwerpia'', ''antwerpia'' from public.locations where slug = ''ghent''',
  'duplicate key', 'LOC194-8 alias nie wskazuje dwóch miejscowości');
select pg_temp.expect_error(
  'insert into public.location_aliases (location_id, alias, alias_key) select id, ''Sint-X'', ''Sint-X'' from public.locations where slug = ''ghent''',
  'location_aliases_key_format', 'LOC194-8b klucz nie w postaci cityKey');
select pg_temp.expect_error(
  'update public.locations set refnis = (select refnis from public.locations where slug = ''antwerp'') where slug = ''ghent''',
  'duplicate key', 'LOC194-8c kod NIS unikalny');

-- Usunięcie miejscowości usuwa jej aliasy (kaskada), bez sierot.
begin;
delete from public.locations where slug = 'namur';
select pg_temp.assert(not exists (select 1 from public.location_aliases where alias_key in ('namur', 'namen')),
  'LOC194-9 aliasy usuwane kaskadowo');
rollback;

-- Kontrola ujemna: bez polityki odczytu klient nie widzi aliasów (RLS włączone, deny).
begin;
drop policy location_aliases_public_read on public.location_aliases;
set role anon; select pg_temp.assert_client_role();
select pg_temp.assert((select count(*) from public.location_aliases) = 0,
  'LOC194-10 kontrola ujemna: bez polityki RLS brak odczytu');
reset role;
rollback;

-- ============================================================================
-- SEC151. Części gmin w słowniku (0151): kind = 'section' z gminą
--         nadrzędną, aliasy PL/NL/FR/EN; nazwa gminy z 0112 wygrywa z nazwą części.
-- ============================================================================
reset role; reset app.current_uid;
select pg_temp.assert(
  (select count(*) from public.locations where kind = 'section' and is_demo = false) >= 1500
  and not exists (select 1 from public.locations s
                   where s.kind = 'section'
                     and not exists (select 1 from public.locations p
                                      where p.id = s.parent_location_id
                                        and p.kind in ('municipality', 'former_municipality')))
  and not exists (select 1 from public.locations s
                   where s.kind = 'section'
                     and not exists (select 1 from public.location_aliases a where a.location_id = s.id)),
  'SEC151-1 części gmin z gminą nadrzędną i aliasem');
select pg_temp.assert(
  (select p.slug from public.location_aliases a
     join public.locations s on s.id = a.location_id
     join public.locations p on p.id = s.parent_location_id
    where a.alias_key = 'heverlee' and s.kind = 'section') = 'leuven'
  and (select p.slug from public.location_aliases a
     join public.locations s on s.id = a.location_id
     join public.locations p on p.id = s.parent_location_id
    where a.alias_key = 'haren' and s.kind = 'section') = 'brussels'
  and (select (latitude, longitude) = (50.891900, 4.418300) from public.locations where slug = 'haren-brussels'),
  'SEC151-2 Heverlee → Leuven, Haren → Bruksela, współrzędne części (nie gminy)');
-- Własna nazwa gminy wygrywa: klucze gmin z 0112 nie wskazują części gmin.
select pg_temp.assert(
  (select l.kind from public.location_aliases a join public.locations l on l.id = a.location_id
    where a.alias_key = 'aalst') = 'municipality'
  and (select l.slug from public.location_aliases a join public.locations l on l.id = a.location_id
    where a.alias_key = 'saint nicolas') = 'saint-nicolas'
  and not exists (select 1 from public.location_aliases a join public.locations l on l.id = a.location_id
                   where l.kind = 'section'
                     and exists (select 1 from public.locations m
                                  where m.kind <> 'section' and m.slug = replace(a.alias_key, ' ', '-'))),
  'SEC151-3 nazwa gminy nie jest przejęta przez część gminy');

-- Zapytanie loadera (src/lib/data/matching.ts) pod rolą klienta i RLS.
set role authenticated; set app.current_uid = :'CANDA'; select pg_temp.assert_client_role();
select pg_temp.assert(
  (select array_agg(format('%s:%s', a.alias_key, l.kind) order by a.alias_key)
     from public.location_aliases a join public.locations l on l.id = a.location_id
    where l.is_active = true and a.alias_key = any(array['heverlee', 'kessel lo', 'leuven']))
  = array['heverlee:section', 'kessel lo:section', 'leuven:municipality'],
  'SEC151-4 loader widzi część gminy i gminę po kluczu');
select pg_temp.expect_error('update public.locations set parent_location_id = null',
  'permission denied', 'SEC151-4b zalogowany nie zmienia powiązania z gminą');
reset role; reset app.current_uid;

-- Integralność: część wymaga gminy; gminą nadrzędną nie może być inna część.
select pg_temp.expect_error(
  'insert into public.locations (slug, name, country, kind) values (''sec191-x'', ''X'', ''BE'', ''section'')',
  'locations_section_parent_check', 'SEC151-5 część gminy bez gminy nadrzędnej');
select pg_temp.expect_error(
  'insert into public.locations (slug, name, country, kind, parent_location_id) select ''sec191-y'', ''Y'', ''BE'', ''section'', id from public.locations where slug = ''heverlee-leuven''',
  'musi wskazywać gminę', 'SEC151-5b gminą nadrzędną nie jest część gminy');
begin;
delete from public.locations where slug = 'leuven';
select pg_temp.assert(not exists (select 1 from public.location_aliases where alias_key in ('heverlee', 'kessel lo')),
  'SEC151-6 usunięcie gminy usuwa jej części i ich aliasy');
rollback;

-- Kontrola ujemna: bez strażnika część wskazuje inną część.
begin;
drop trigger locations_section_parent_guard on public.locations;
insert into public.locations (slug, name, country, kind, parent_location_id)
  select 'sec191-y', 'Y', 'BE', 'section', id from public.locations where slug = 'heverlee-leuven';
select pg_temp.assert(exists (select 1 from public.locations where slug = 'sec191-y'),
  'SEC151-7 kontrola ujemna: bez strażnika część gminy wskazuje część');
rollback;
-- Kontrola ujemna: bez danych 0151 nazwa części gminy jest nieznana (brak wiersza loadera).
begin;
delete from public.locations where kind = 'section';
select pg_temp.assert(not exists (select 1 from public.location_aliases where alias_key = 'heverlee'),
  'SEC151-8 kontrola ujemna: bez części gmin Heverlee nie ma współrzędnych');
rollback;

-- ============================================================================
-- AC45. Panel admina kampanii e-mail (#45, 0111): admin_activate/cancel_email_campaign —
--       tylko admin (is_admin), CAS statusu (STALE_STATE), macierz przejść
--       (INVALID_TRANSITION), skutek = istniejące RPC z 0101, audyt bez treści i odbiorców.
-- ============================================================================
reset role; reset app.current_uid;
select public.create_email_campaign_revision('ac45-news', :'CMJOBS'::jsonb) as ac_rev1 \gset

-- AC45-1: anon bez EXECUTE; kandydat i pracodawca → PERMISSION_DENIED, bez zmiany stanu.
set role anon; reset app.current_uid; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_activate_email_campaign(%L, ''draft'')', :'ac_rev1'),
  'permission denied', 'AC45-1 anon nie wywoła aktywacji');
reset role;
set role authenticated; set app.current_uid = :'CANDA'; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_activate_email_campaign(%L, ''draft'')', :'ac_rev1'),
  'PERMISSION_DENIED', 'AC45-1b kandydat nie aktywuje');
select pg_temp.expect_error(format('select public.activate_email_campaign(%L)', :'ac_rev1'),
  'permission denied', 'AC45-1c kandydat nie wywoła RPC service_role z 0101');
reset role; reset app.current_uid;
set role authenticated; set app.current_uid = :'EMPA'; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_cancel_email_campaign(%L, ''draft'')', :'ac_rev1'),
  'PERMISSION_DENIED', 'AC45-1d pracodawca nie zatrzyma');
select pg_temp.expect_error('select count(*) from public.email_campaigns', 'permission denied',
  'AC45-1e pracodawca nie czyta tabeli kampanii');
reset role; reset app.current_uid;
select pg_temp.assert((select status from public.email_campaigns where id = :'ac_rev1') = 'draft',
  'AC45-1f odmowy nie zmieniły rewizji');

-- AC45-2: CAS — admin widział inny status → STALE_STATE, bez zmiany i bez audytu.
set role authenticated; set app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_activate_email_campaign(%L, ''active'')', :'ac_rev1'),
  'STALE_STATE', 'AC45-2 nieaktualny status → STALE_STATE');
select pg_temp.expect_error(format('select public.admin_cancel_email_campaign(%L, null)', :'ac_rev1'),
  'STALE_STATE', 'AC45-2b brak oczekiwanego statusu → STALE_STATE');
select pg_temp.expect_error(format('select public.admin_activate_email_campaign(%L, ''draft'')', gen_random_uuid()),
  'NOT_FOUND', 'AC45-2c nieistniejąca rewizja → NOT_FOUND');
reset role; reset app.current_uid;
select pg_temp.assert(
  (select status from public.email_campaigns where id = :'ac_rev1') = 'draft'
  and not exists (select 1 from public.audit_logs where entity_id = :'ac_rev1'::uuid),
  'AC45-2d po odmowie: szkic bez zmian, brak wpisu w dzienniku');

-- AC45-3: aktywacja szkicu przez admina + audyt (aktor = admin, bez treści kampanii).
set role authenticated; set app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_activate_email_campaign(:'ac_rev1', 'draft');
select pg_temp.expect_error(format('select public.admin_activate_email_campaign(%L, ''active'')', :'ac_rev1'),
  'INVALID_TRANSITION', 'AC45-3 aktywna rewizja nie jest ponownie aktywowana');
reset role; reset app.current_uid;
select pg_temp.assert(
  (select status = 'active' and activated_at is not null from public.email_campaigns where id = :'ac_rev1'),
  'AC45-3b szkic aktywny');
select pg_temp.assert(
  (select count(*) = 1 and bool_and(actor_id = :'ADMIN'::uuid and entity_type = 'email_campaign'
                                    and before_data ->> 'status' = 'draft' and after_data ->> 'status' = 'active'
                                    and not (after_data ? 'content') and not (before_data ? 'content'))
     from public.audit_logs where action = 'email_campaign.activated' and entity_id = :'ac_rev1'::uuid),
  'AC45-3c audyt aktywacji: admin, statusy, bez treści');

-- AC45-4: aktywacja nowszej rewizji zastępuje poprzednią (skutek 0101), audyt ją wymienia.
select public.create_email_campaign_revision('ac45-news', :'CMJOBS'::jsonb) as ac_rev2 \gset
set role authenticated; set app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_activate_email_campaign(:'ac_rev2', 'draft');
select pg_temp.expect_error(format('select public.admin_cancel_email_campaign(%L, ''superseded'')', :'ac_rev1'),
  'INVALID_TRANSITION', 'AC45-4 zastąpionej rewizji nie da się zatrzymać');
reset role; reset app.current_uid;
select pg_temp.assert(
  (select status from public.email_campaigns where id = :'ac_rev1') = 'superseded'
  and (select status from public.email_campaigns where id = :'ac_rev2') = 'active'
  and (select after_data -> 'superseded' -> 0 ->> 'id' from public.audit_logs
        where action = 'email_campaign.activated' and entity_id = :'ac_rev2'::uuid) = :'ac_rev1',
  'AC45-4b poprzednia rewizja zastąpiona i wymieniona w audycie');

-- AC45-5: zatrzymanie aktywnej rewizji — zakolejkowany list wygaszony, odbiorca cancelled,
--         audyt z liczbą wygaszonych listów; ponowienie ze starym statusem → STALE_STATE.
insert into public.email_deliveries(profile_id, to_email, template, status, entity_type, entity_id,
                                    idempotency_key, campaign_id)
values (:'CMN1', 'cmn1@test.be', 'newsletter', 'queued', 'email_campaign', :'ac_rev2',
        'campaign:' || :'ac_rev2' || ':' || :'CMN1', :'ac_rev2')
returning id as ac_delivery \gset
insert into public.email_campaign_recipients(campaign_id, profile_id, status, delivery_id)
values (:'ac_rev2', :'CMN1', 'queued', :'ac_delivery');
set role authenticated; set app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_cancel_email_campaign(:'ac_rev2', 'active');
select pg_temp.expect_error(format('select public.admin_cancel_email_campaign(%L, ''active'')', :'ac_rev2'),
  'STALE_STATE', 'AC45-5 drugi admin ze starym widokiem → STALE_STATE');
reset role; reset app.current_uid;
select pg_temp.assert(
  (select status from public.email_campaigns where id = :'ac_rev2') = 'cancelled'
  and (select status::text || '/' || error_message from public.email_deliveries where id = :'ac_delivery')
      = 'failed/suppressed_campaign_inactive'
  and (select status || '/' || reason from public.email_campaign_recipients
        where campaign_id = :'ac_rev2' and profile_id = :'CMN1') = 'cancelled/cancelled',
  'AC45-5b rewizja zatrzymana, list wygaszony, odbiorca cancelled');
select pg_temp.assert(
  (select (after_data ->> 'suppressed_deliveries')::int = 1 and actor_id = :'ADMIN'::uuid
          and not (after_data ? 'profile_id') and not (after_data ? 'to_email')
     from public.audit_logs where action = 'email_campaign.cancelled' and entity_id = :'ac_rev2'::uuid),
  'AC45-5c audyt zatrzymania: liczba listów, bez danych odbiorcy');

-- AC45-6: KONTROLA UJEMNA — wersja bez porównania statusu przepuściłaby decyzję opartą
--         na nieaktualnym widoku (asercja AC45-2 wykrywa brak CAS).
begin;
create or replace function public.admin_cancel_email_campaign(p_campaign_id uuid, p_expected_status text)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then raise exception 'PERMISSION_DENIED' using errcode = '42501'; end if;
  perform public.cancel_email_campaign(p_campaign_id);
end $$;
select public.create_email_campaign_revision('ac45-neg', :'CMJOBS'::jsonb) as ac_neg \gset
set local role authenticated; set local app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_cancel_email_campaign(:'ac_neg', 'active');
reset role;
select pg_temp.assert((select status from public.email_campaigns where id = :'ac_neg') = 'cancelled',
  'AC45-6 bez CAS nieaktualny widok (active ≠ draft) zatrzymuje rewizję — test wykrywa błąd');
rollback;
reset role; reset app.current_uid;

-- ============================================================================
-- SU47. Wyszukiwanie ofert bez diakrytyków i z literalnym %/_/\ (0110, #47):
--       get_public_jobs/_count/facety składają tytuł i miasto przez search_fold
--       (lower + unaccent) i escapują wpis użytkownika. Prefiltr po indeksach nie
--       zmienia wyniku (dokładny warunek na wyświetlanym tytule w locale).
-- ============================================================================
\set SUCO  'e8000000-0000-0000-0000-0000000047c0'
\set SUJA  'e8000000-0000-0000-0000-0000000047a1'
\set SUJB  'e8000000-0000-0000-0000-0000000047a2'
\set SUJC  'e8000000-0000-0000-0000-0000000047a3'
\set SUJD  'e8000000-0000-0000-0000-0000000047a4'
reset role; reset app.current_uid;
begin;
insert into public.companies(id, name, status) values (:'SUCO', 'SU47 Firma', 'verified');
insert into public.jobs(id,company_id,slug,title,category,contract_type,city,region,status,default_locale,published_at) values
  (:'SUJA',:'SUCO','su47-a','Pracownik sprzątania SU47X','cleaning','permanent','Liège','Walonia','active','pl', now() - interval '1 hour'),
  (:'SUJB',:'SUCO','su47-b','Rabat 50% SU47X','warehouse','permanent','Bruxelles','Bruksela','active','pl', now() - interval '2 hours'),
  (:'SUJC',:'SUCO','su47-c','Kierowca_C SU47X','transport','permanent','Gent','Flandria','active','pl', now() - interval '3 hours'),
  (:'SUJD',:'SUCO','su47-d','Magazynier SU47X','warehouse','permanent','Namur','Walonia','active','pl', now() - interval '4 hours');
insert into public.job_translations(job_id, locale, title) values
  (:'SUJD','pl','Magazynier SU47X'),
  (:'SUJD','fr','Préparateur de commandes SU47X');

set role anon; reset app.current_uid; select pg_temp.assert_client_role();
-- SU47-1: diakrytyki i wielkość liter po obu stronach.
select pg_temp.assert(
  public.get_public_jobs_count('pl', 'sprzatania su47x') = 1
  and public.get_public_jobs_count('pl', 'SPRZĄTANIA SU47X') = 1
  and (select array_agg(slug) from public.get_public_jobs('pl', 'SPRZATANIA su47x')) = array['su47-a'],
  'SU47-1 słowo kluczowe bez diakrytyków i wielkości liter znajduje ofertę');

-- SU47-2: `%`, `_` i `\` we wpisie są literałami (dotąd `%su47x` pasowało do każdej oferty).
select pg_temp.assert(
  public.get_public_jobs_count('pl', '%su47x') = 0
  and public.get_public_jobs_count('pl', '50% su47x') = 1
  and public.get_public_jobs_count('pl', 'a_c su47x') = 1
  and public.get_public_jobs_count('pl', 'm_gazynier su47x') = 0
  and public.get_public_jobs_count('pl', 'su47x\') = 0
  and public.get_public_jobs_count('pl', 'su47x', '%') = 0,
  'SU47-2 %/_/\ w słowie kluczowym i mieście działają literalnie');

-- SU47-3: miasto bez diakrytyków; wynik listy, licznika i facetów zgodny.
select pg_temp.assert(
  (select array_agg(slug) from public.get_public_jobs('pl', 'su47x', 'liege')) = array['su47-a']
  and public.get_public_jobs_count('pl', 'su47x', 'LIÈGE') = 1
  and (select total from public.get_public_job_filter_facets('pl', 'su47x', 'liege')
       where dimension = 'total') = 1
  and (select total from public.get_public_job_filter_facets('pl', 'sprzatania su47x')
       where dimension = 'total') = 1
  and (select total from public.get_public_job_filter_facets('pl', '%su47x')
       where dimension = 'total') = 0,
  'SU47-3 miasto bez diakrytyków; lista = licznik = facety');

-- SU47-4: dopasowanie liczy się na tytule wyświetlanym w locale — tłumaczenie fr pasuje
-- tylko dla fr, mimo że prefiltr (dowolne tłumaczenie) obejmuje ofertę także dla pl.
select pg_temp.assert(
  public.get_public_jobs_count('fr', 'preparateur de commandes su47x') = 1
  and public.get_public_jobs_count('pl', 'preparateur de commandes su47x') = 0
  and (select array_agg(title) from public.get_public_jobs('fr', 'preparateur de commandes su47x'))
      = array['Préparateur de commandes SU47X'],
  'SU47-4 tytuł w locale zapytania; prefiltr nie dodaje trafień z innego języka');

-- SU47-5 (kontrola ujemna): stary warunek ILIKE z 0091 na tych samych danych nie znajduje
-- zapisu bez diakrytyków i traktuje `%` jako symbol wieloznaczny.
reset role;
select pg_temp.assert(
  (select count(*) from public.jobs where title ilike '%' || 'sprzatania su47x' || '%') = 0
  and (select count(*) from public.jobs where title ilike '%' || '%su47x' || '%') = 4
  and (select count(*) from public.jobs where city ilike '%' || 'liege' || '%' and id = :'SUJA') = 0,
  'SU47-5 kontrola ujemna: ILIKE bez search_fold/escapowania daje inny wynik');
rollback;

-- SU47-6: funkcje pomocnicze — składanie niezmienne (indeks wyrażeniowy), escapowanie.
select pg_temp.assert(
  public.search_fold('Liège ŁÓDŹ Șofer Préparateur') = 'liege lodz sofer preparateur'
  and public.search_like_pattern('50%_\x') = '%50\%\_\\x%'
  and (select provolatile from pg_proc where oid = 'public.search_fold(text)'::regprocedure) = 'i'
  and (select count(*) from pg_indexes where schemaname = 'public' and indexname in (
        'idx_jobs_title_fold_trgm', 'idx_job_translations_title_fold_trgm', 'idx_jobs_city_fold_trgm')) = 3
  and not exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'idx_jobs_city_trgm'),
  'SU47-6 search_fold IMMUTABLE, wzorzec escapowany, indeksy fold na miejscu');

-- SU47-7: indeksy obejmują dokładnie wyrażenia prefiltrów (search_fold(kolumna)) i predykat
-- listy ofert — inaczej planista nie mógłby ich użyć. Wybór planu przy realnej liczbie ofert
-- mierzy scripts/db/search-benchmark.sh (plan zależy od statystyk, więc nie tu).
select pg_temp.assert(
  pg_get_indexdef('public.idx_jobs_title_fold_trgm'::regclass)
    like '%USING gin (search_fold(title) gin_trgm_ops) WHERE ((status = ''active''::job_status) AND (deleted_at IS NULL))'
  and pg_get_indexdef('public.idx_jobs_city_fold_trgm'::regclass)
    like '%USING gin (search_fold(city) gin_trgm_ops) WHERE ((status = ''active''::job_status) AND (deleted_at IS NULL))'
  and pg_get_indexdef('public.idx_job_translations_title_fold_trgm'::regclass)
    like '%USING gin (search_fold(title) gin_trgm_ops)',
  'SU47-7 indeksy GIN na search_fold(title/city), częściowe jak predykat listy');

-- SU47-8: funkcje kandydatów tylko dla właściciela RPC (bez EXECUTE dla ról aplikacji);
-- granty RPC bez zmian.
select pg_temp.assert(
  not has_function_privilege('anon', 'public.search_title_candidates(text)', 'execute')
  and not has_function_privilege('authenticated', 'public.search_title_candidates(text)', 'execute')
  and not has_function_privilege('anon', 'public.search_city_candidates(text)', 'execute')
  and not has_function_privilege('authenticated', 'public.search_city_candidates(text)', 'execute')
  and has_function_privilege('anon', 'public.get_public_jobs(text,text,text,text[],text[],text[],integer,integer,boolean,boolean,boolean,timestamptz,text,integer,integer,text,boolean,text,text,text,text,integer,text[])', 'execute')
  and has_function_privilege('anon', 'public.get_public_job_filter_facets(text,text,text,text[],text[],text[],integer,integer,boolean,boolean,boolean,timestamptz,text,boolean,text,text,text,text,integer,text[])', 'execute')
  and not has_function_privilege('public', 'public.get_public_jobs_count(text,text,text,text[],text[],text[],integer,integer,boolean,boolean,boolean,timestamptz,text,boolean,text,text,text,text,integer,text[])', 'execute'),
  'SU47-8 funkcje kandydatów bez EXECUTE dla anon/authenticated; granty RPC jak w 0091');

-- =============================================================================
-- TR33 (#33, 0146): oferta → kolejka tłumaczeń przy każdej zatwierdzonej zmianie (odroczone
-- triggery). Źródło w języku oferty (tu nl), wymagania tekstowe w polach, publish/pause/resume/
-- wygaśnięcie/zawieszenie firmy/usunięcie, rollback, stawka poza tłumaczeniem, dwie sesje
-- równolegle i kontrola ujemna TR33-N (bez triggera kolejka zostaje przy starej treści).
-- =============================================================================
\set TRCO  'f0330000-0000-0000-0000-0000000000c1'
\set TRJ1  'f0330000-0000-0000-0000-0000000000a1'
\set TRJ2  'f0330000-0000-0000-0000-0000000000a2'
\set TRJ3  'f0330000-0000-0000-0000-0000000000a3'
\set TRJ4  'f0330000-0000-0000-0000-0000000000a4'
reset role; reset app.current_uid;
-- Izolacja: zadania ofert z wcześniejszych sekcji nie trafiają do claimów tej sekcji.
select count(public.deactivate_translation_source(entity_type, entity_id, false)) from public.translation_sources;
insert into public.companies(id, name, status) values (:'TRCO', 'Firma TR33', 'verified');
insert into public.jobs(id, company_id, slug, title, category, contract_type, city, region, status, default_locale,
                        salary_min, salary_max, salary_period)
  values (:'TRJ1', :'TRCO', 'draft-tr33', 'Magazijnmedewerker', 'warehouse', 'permanent', 'Gent', 'Vlaanderen', 'draft', 'nl',
          15, 17, 'hour');
insert into public.job_translations(job_id, locale, title, description, responsibilities, benefits)
  values (:'TRJ1', 'nl', 'Magazijnmedewerker', 'Werk in het magazijn vanaf 8:00. Geen ervaring nodig.',
          array['Orders verzamelen', 'Laden'], array['Parking']);
insert into public.job_requirements(job_id, locale, kind, position, content) values
  (:'TRJ1', 'nl', 'mandatory', 0, 'VCA-certificaat'),
  (:'TRJ1', 'nl', 'mandatory', 1, 'Nachtwerk'),
  (:'TRJ1', 'nl', 'optional', 0, 'Heftruck'),
  (:'TRJ1', 'pl', 'mandatory', 0, 'Wiersz w innym języku');

-- TR33-1: szkic nie trafia do kolejki (bez kosztu dla kreatora).
select pg_temp.assert(not exists (select 1 from public.translation_sources where entity_id = :'TRJ1'),
  'TR33-1 szkic bez źródła tłumaczenia');

-- TR33-2: publikacja → rewizja 1 w języku oferty + zadania pl/fr/en; wymagania tekstowe w polach.
update public.jobs set status = 'active', published_at = now() where id = :'TRJ1';
select pg_temp.assert((select current_revision_no = 1 and is_active from public.translation_sources
  where entity_type = 'job' and entity_id = :'TRJ1'), 'TR33-2 publikacja = rewizja 1');
select r.id as tr33_rev1, r.fields::text as tr33_f1 from public.translation_source_revisions r
 where r.entity_id = :'TRJ1' and r.revision_no = 1 \gset
select pg_temp.assert((select source_locale = 'nl' from public.translation_source_revisions where id = :'tr33_rev1')
  and (select array_agg(target_locale order by target_locale) from public.translation_jobs where revision_id = :'tr33_rev1')
      = array['en', 'fr', 'pl'], 'TR33-2b źródło nl, zadania en/fr/pl');
select pg_temp.assert((:'tr33_f1'::jsonb)->>'requirements_mandatory.0' = 'VCA-certificaat'
  and (:'tr33_f1'::jsonb)->>'requirements_mandatory.1' = 'Nachtwerk'
  and (:'tr33_f1'::jsonb)->>'requirements_optional.0' = 'Heftruck'
  and (:'tr33_f1'::jsonb)->>'responsibilities.1' = 'Laden'
  and (:'tr33_f1'::jsonb)->>'benefits.0' = 'Parking'
  and (:'tr33_f1'::jsonb)->>'title' = 'Magazijnmedewerker'
  and not (:'tr33_f1'::text like '%Wiersz w innym%')
  and not ((:'tr33_f1'::jsonb) ? 'meta_title'),
  'TR33-2c pola: tytuł, opis, listy i wymagania w języku oferty (bez pustych, bez innego języka)');

-- TR33-3: rollback edycji nie zostawia śladu w kolejce.
begin;
update public.job_translations set description = 'Wycofana zmiana.' where job_id = :'TRJ1' and locale = 'nl';
rollback;
select pg_temp.assert((select current_revision_no from public.translation_sources where entity_id = :'TRJ1') = 1
  and (select count(*) from public.translation_source_revisions where entity_id = :'TRJ1') = 1,
  'TR33-3 rollback: brak nowej rewizji');

-- TR33-4: stawka, miasto i licznik nie są polami tłumaczenia — bez rewizji i bez kosztu;
-- wartość czytana z jobs jest od razu wspólna dla wszystkich języków.
update public.jobs set salary_min = 16, salary_max = 18, city = 'Gent-Zuid', views_count = views_count + 1
 where id = :'TRJ1';
select pg_temp.assert((select current_revision_no from public.translation_sources where entity_id = :'TRJ1') = 1
  and (select count(*) from public.translation_jobs where entity_id = :'TRJ1') = 3,
  'TR33-4 zmiana stawki bez nowej rewizji i zadań');

-- TR33-5: przekład en dla rewizji 1, potem edycja w JEDNEJ transakcji (opis + replace-all wymagań)
-- = dokładnie jedna nowa rewizja z końcową treścią (bez stanów pośrednich); stare zadania
-- superseded, przekład en nieaktualny.
reset role; create temp table tr33_claim as select * from public.claim_translation_jobs(100, 300);
select job_id as tr33_en, lease_id as tr33_en_lease from tr33_claim where entity_id = :'TRJ1' and target_locale = 'en' \gset
select job_id as tr33_fr, lease_id as tr33_fr_lease from tr33_claim where entity_id = :'TRJ1' and target_locale = 'fr' \gset
set role service_role;
select pg_temp.assert(public.complete_translation_job(:'tr33_en', :'tr33_en_lease',
  replace(replace(replace(replace(replace(replace(replace(replace(:'tr33_f1',
    'Magazijnmedewerker', 'Warehouse worker'),
    'Werk in het magazijn vanaf 8:00. Geen ervaring nodig.', 'Warehouse work from 8:00. No experience required.'),
    'Orders verzamelen', 'Order picking'), 'Laden', 'Loading'), 'VCA-certificaat', 'VCA certificate'),
    'Nachtwerk', 'Night work'), 'Heftruck', 'Forklift'), 'Parking', 'Parking')::jsonb) = 'applied',
  'TR33-5 przekład en rewizji 1 zastosowany');
reset role;
begin;
update public.job_translations set description = 'Werk in het magazijn vanaf 22:00. Geen ervaring nodig.'
 where job_id = :'TRJ1' and locale = 'nl';
delete from public.job_requirements where job_id = :'TRJ1' and locale = 'nl' and kind = 'mandatory';
insert into public.job_requirements(job_id, locale, kind, position, content) values
  (:'TRJ1', 'nl', 'mandatory', 0, 'VCA-certificaat'),
  (:'TRJ1', 'nl', 'mandatory', 1, 'Rijbewijs B');
commit;
select pg_temp.assert((select current_revision_no from public.translation_sources where entity_id = :'TRJ1') = 2
  and (select count(*) from public.translation_source_revisions where entity_id = :'TRJ1') = 2,
  'TR33-5b jedna transakcja = jedna nowa rewizja');
select id as tr33_rev2 from public.translation_source_revisions where entity_id = :'TRJ1' and revision_no = 2 \gset
select pg_temp.assert((select fields->>'description' like '%22:00%' and fields->>'requirements_mandatory.1' = 'Rijbewijs B'
  and not (fields ? 'requirements_mandatory.2') from public.translation_source_revisions where id = :'tr33_rev2'),
  'TR33-5c rewizja 2 = końcowa treść (opis + wymagania)');
select pg_temp.assert((select bool_and(status = 'superseded') from public.translation_jobs
  where revision_id = :'tr33_rev1' and target_locale in ('fr', 'pl'))
  and (select count(*) from public.translation_jobs where revision_id = :'tr33_rev2' and status = 'queued') = 3
  and (select is_stale and revision_no = 1 from public.translation_documents where entity_id = :'TRJ1' and locale = 'en'),
  'TR33-5d zadania rewizji 1 superseded, trzy zadania rewizji 2, przekład en nieaktualny');
set role service_role;
select pg_temp.assert(public.complete_translation_job(:'tr33_fr', :'tr33_fr_lease', :'tr33_f1'::jsonb) = 'superseded',
  'TR33-5e spóźniony wynik rewizji 1 po edycji = superseded (bez mieszania rewizji)');
reset role; drop table tr33_claim;

-- TR33-6: korekta ręczna (fr) przetrwa kolejną edycję — AI jej nie nadpisze (wynik = proposal).
set role service_role;
select public.save_manual_translation('job', :'TRJ1', 'fr',
  (select fields from public.translation_source_revisions where id = :'tr33_rev2'), :'ADMIN') as tr33_manual \gset
reset role;
update public.job_translations set title = 'Magazijnmedewerker (nacht)' where job_id = :'TRJ1' and locale = 'nl';
select id as tr33_rev3, fields::text as tr33_f3 from public.translation_source_revisions
 where entity_id = :'TRJ1' and revision_no = 3 \gset
create temp table tr33_claim as select * from public.claim_translation_jobs(100, 300);
select job_id as tr33_fr3, lease_id as tr33_fr3_lease from tr33_claim where entity_id = :'TRJ1' and target_locale = 'fr' \gset
select job_id as tr33_pl3, lease_id as tr33_pl3_lease from tr33_claim where entity_id = :'TRJ1' and target_locale = 'pl' \gset
set role service_role;
select pg_temp.assert(public.complete_translation_job(:'tr33_fr3', :'tr33_fr3_lease', :'tr33_f3'::jsonb) = 'proposal',
  'TR33-6 wynik AI przy korekcie ręcznej = proposal');
reset role;
select pg_temp.assert((select origin = 'manual' and is_locked and manual_author = :'ADMIN'
  from public.translation_documents where entity_id = :'TRJ1' and locale = 'fr'),
  'TR33-6b korekta ręczna nietknięta po edycji oferty');
drop table tr33_claim;

-- TR33-7: wstrzymanie → źródło nieaktywne, zaległe zadania superseded, spóźniony wynik nic nie
-- publikuje; wznowienie tej samej treści → requeued bez nowej rewizji.
update public.jobs set status = 'paused' where id = :'TRJ1';
select pg_temp.assert((select not is_active from public.translation_sources where entity_id = :'TRJ1')
  and not exists (select 1 from public.translation_jobs where entity_id = :'TRJ1' and status in ('queued', 'retry', 'leased')),
  'TR33-7 wstrzymanie: źródło nieaktywne, brak zaległych zadań');
set role service_role;
select pg_temp.assert(public.complete_translation_job(:'tr33_pl3', :'tr33_pl3_lease', :'tr33_f3'::jsonb) = 'superseded',
  'TR33-7b wynik po wstrzymaniu = superseded');
reset role;
select pg_temp.assert(not exists (select 1 from public.translation_documents where entity_id = :'TRJ1' and locale = 'pl'),
  'TR33-7c nic nie opublikowano');
update public.jobs set status = 'active' where id = :'TRJ1';
select pg_temp.assert((select is_active and current_revision_no = 3 from public.translation_sources where entity_id = :'TRJ1')
  and (select count(*) from public.translation_jobs where revision_id = :'tr33_rev3' and status = 'queued') >= 2,
  'TR33-7d wznowienie: ta sama rewizja, zadania wracają do kolejki');

-- TR33-8: zawieszenie firmy i wygaśnięcie ukrywają źródło; powrót = ponowna aktywacja.
update public.companies set status = 'suspended' where id = :'TRCO';
select pg_temp.assert((select not is_active from public.translation_sources where entity_id = :'TRJ1'),
  'TR33-8 zawieszona firma: źródło nieaktywne');
update public.companies set status = 'verified' where id = :'TRCO';
select pg_temp.assert((select is_active from public.translation_sources where entity_id = :'TRJ1'),
  'TR33-8b firma zweryfikowana ponownie: źródło aktywne');
update public.jobs set expires_at = now() - interval '1 minute' where id = :'TRJ1';
select pg_temp.assert((select not is_active from public.translation_sources where entity_id = :'TRJ1'),
  'TR33-8c oferta po terminie: źródło nieaktywne');
update public.jobs set expires_at = null where id = :'TRJ1';

-- TR33-9: dwie sesje równolegle — sesja B edytuje opis (niezatwierdzona), sesja główna zmienia
-- wymagania i zatwierdza; po commicie B bieżąca rewizja ma OBIE zmiany (kolejka nie gubi edycji).
select pg_temp.remote_connect('tr33b');
select dbl.dblink_exec('tr33b', 'begin');
select dbl.dblink_exec('tr33b', format(
  'update public.job_translations set description = %L where job_id = %L and locale = ''nl''',
  'Werk in het magazijn vanaf 6:00. Geen ervaring nodig.', :'TRJ1'));
update public.job_requirements set content = 'Heftruckcertificaat' where job_id = :'TRJ1' and kind = 'optional';
select pg_temp.assert((select fields->>'requirements_optional.0' = 'Heftruckcertificaat' and fields->>'description' like '%22:00%'
  from public.translation_source_revisions r join public.translation_sources s on s.current_revision_id = r.id
  where s.entity_id = :'TRJ1'), 'TR33-9 commit sesji głównej: rewizja z jej zmianą');
select dbl.dblink_exec('tr33b', 'commit');
select dbl.dblink_disconnect('tr33b');
select pg_temp.assert((select fields->>'requirements_optional.0' = 'Heftruckcertificaat' and fields->>'description' like '%6:00%'
  from public.translation_source_revisions r join public.translation_sources s on s.current_revision_id = r.id
  where s.entity_id = :'TRJ1'), 'TR33-9b commit sesji B: bieżąca rewizja ma obie zmiany');
select pg_temp.assert((select count(*) from public.translation_jobs j join public.translation_sources s
  on s.entity_id = j.entity_id and s.entity_type = j.entity_type
  where j.entity_id = :'TRJ1' and j.status in ('queued', 'retry', 'leased') and j.revision_id <> s.current_revision_id) = 0,
  'TR33-9c brak zaległych zadań starszych rewizji');

-- TR33-10: treść ponad limit pól nie blokuje publikacji — źródło ukryte (skipped).
insert into public.jobs(id, company_id, slug, title, category, contract_type, city, region, status, default_locale)
  values (:'TRJ2', :'TRCO', 'draft-tr33-2', 'Oferta duża', 'warehouse', 'permanent', 'Gent', 'Vlaanderen', 'draft', 'pl');
insert into public.job_translations(job_id, locale, title, description, responsibilities)
  values (:'TRJ2', 'pl', 'Oferta duża', 'Opis.', array(select 'Zadanie ' || g from generate_series(1, 90) g));
update public.jobs set status = 'active' where id = :'TRJ2';
select pg_temp.assert((select status::text from public.jobs where id = :'TRJ2') = 'active'
  and (select public.sync_job_translation_source(:'TRJ2')) = 'skipped'
  and not exists (select 1 from public.translation_jobs where entity_id = :'TRJ2'),
  'TR33-10 za dużo pól: oferta aktywna, tłumaczenie pominięte');

-- TR33-11: oferta demonstracyjna nie trafia do kolejki (Invariant #12, bez kosztu AI).
insert into public.jobs(id, company_id, slug, title, category, contract_type, city, region, status, default_locale, is_demo)
  values (:'TRJ3', :'TRCO', 'draft-tr33-3', 'Oferta demo', 'warehouse', 'permanent', 'Gent', 'Vlaanderen', 'draft', 'pl', true);
insert into public.job_translations(job_id, locale, title, description) values (:'TRJ3', 'pl', 'Oferta demo', 'Opis demo.');
update public.jobs set status = 'active' where id = :'TRJ3';
select pg_temp.assert(not exists (select 1 from public.translation_sources where entity_id = :'TRJ3'),
  'TR33-11 oferta demo bez źródła tłumaczenia');

-- TR33-12: usunięcie (soft delete i fizyczne) = purge rewizji, zadań i przekładów (także korekt).
update public.jobs set deleted_at = now() where id = :'TRJ1';
select pg_temp.assert(not exists (select 1 from public.translation_sources where entity_id = :'TRJ1')
  and not exists (select 1 from public.translation_source_revisions where entity_id = :'TRJ1')
  and not exists (select 1 from public.translation_jobs where entity_id = :'TRJ1')
  and not exists (select 1 from public.translation_documents where entity_id = :'TRJ1'),
  'TR33-12 soft delete: purge');
insert into public.jobs(id, company_id, slug, title, category, contract_type, city, region, status, default_locale)
  values (:'TRJ4', :'TRCO', 'draft-tr33-4', 'Oferta do usunięcia', 'warehouse', 'permanent', 'Gent', 'Vlaanderen', 'draft', 'fr');
insert into public.job_translations(job_id, locale, title, description) values (:'TRJ4', 'fr', 'Magasinier', 'Travail en entrepôt.');
update public.jobs set status = 'active' where id = :'TRJ4';
select pg_temp.assert((select source_locale from public.translation_source_revisions where entity_id = :'TRJ4') = 'fr'
  and (select array_agg(target_locale order by target_locale) from public.translation_jobs where entity_id = :'TRJ4')
      = array['en', 'nl', 'pl'], 'TR33-12b źródło fr: zadania en/nl/pl');
delete from public.jobs where id = :'TRJ4';
select pg_temp.assert(not exists (select 1 from public.translation_sources where entity_id = :'TRJ4')
  and not exists (select 1 from public.translation_jobs where entity_id = :'TRJ4'),
  'TR33-12c usunięcie fizyczne: purge');

-- TR33-13: funkcje synchronizacji niedostępne dla ról klienta.
select pg_temp.assert(
  not has_function_privilege('authenticated', 'public.sync_job_translation_source(uuid)', 'execute')
  and not has_function_privilege('anon', 'public.sync_job_translation_source(uuid)', 'execute')
  and not has_function_privilege('authenticated', 'public.job_translation_source_fields(uuid)', 'execute')
  and public.translation_pipeline_version() ~ '^[a-z0-9][a-z0-9.+_-]{0,63}$',
  'TR33-13 synchronizacja tylko dla serwera; wersja pipeline zgodna z CHECK');

-- TR33-N (kontrola ujemna): bez triggera na job_translations edycja aktywnej oferty zostawia
-- kolejkę przy starej treści — to trigger (a nie przypadek) utrzymuje rewizję w zgodzie z ofertą.
begin;
alter table public.job_translations disable trigger trg_job_translation_sync_translations;
update public.job_translations set responsibilities = array['Jedno zadanie'] where job_id = :'TRJ2' and locale = 'pl';
set constraints all immediate;
select pg_temp.assert((select public.sync_job_translation_source(:'TRJ2')) = 'created', 'TR33-Na ręczna synchronizacja tworzy rewizję');
rollback;
begin;
alter table public.job_translations disable trigger trg_job_translation_sync_translations;
update public.job_translations set responsibilities = array['Jedno zadanie'] where job_id = :'TRJ2' and locale = 'pl';
set constraints all immediate;
select pg_temp.assert(not exists (select 1 from public.translation_jobs where entity_id = :'TRJ2'),
  'TR33-N bez triggera edycja nie trafia do kolejki');
rollback;
update public.job_translations set responsibilities = array['Jedno zadanie'] where job_id = :'TRJ2' and locale = 'pl';
select pg_temp.assert((select count(*) from public.translation_jobs where entity_id = :'TRJ2' and status = 'queued') = 3,
  'TR33-Nb z triggerem ta sama edycja kolejkuje trzy zadania');

-- =============================================================================
-- TP740 (#740, 0190): nazwy chronione w kolejce tłumaczeń. Nazwa firmy z bazy trafia do
-- rewizji oferty (nigdy od klienta), claim wydaje ją workerowi, zmiana nazwy firmy = nowa
-- rewizja; normalizacja i limity; rewizja niezmienna. Kontrole ujemne: odcisk z 0145 (bez
-- nazw) nie odróżnia zmiany nazwy, trigger firmy z 0146 (bez `name`) nie reaguje na zmianę.
-- =============================================================================
\set TPCO 'f0740000-0000-0000-0000-0000000000c1'
\set TPJ1 'f0740000-0000-0000-0000-0000000000a1'
\set TPE1 'f0740000-0000-0000-0000-0000000000e1'
reset role; reset app.current_uid;
insert into public.companies(id, name, status) values (:'TPCO', 'Logistiek Noord', 'verified');
insert into public.jobs(id, company_id, slug, title, category, contract_type, city, region, status, default_locale)
  values (:'TPJ1', :'TPCO', 'draft-tp740', 'Magazijnmedewerker', 'warehouse', 'permanent', 'Gent', 'Vlaanderen', 'draft', 'nl');
insert into public.job_translations(job_id, locale, title, description)
  values (:'TPJ1', 'nl', 'Magazijnmedewerker', 'Logistiek Noord zoekt een magazijnmedewerker.');
update public.jobs set status = 'active', published_at = now() where id = :'TPJ1';

-- TP740-1: publikacja → rewizja z nazwą firmy z bazy; claim wydaje ją workerowi.
select r.id as tp_rev1, r.content_hash as tp_hash1, r.fields::text as tp_f1
  from public.translation_source_revisions r where r.entity_id = :'TPJ1' and r.revision_no = 1 \gset
select pg_temp.assert((select protected_terms = array['Logistiek Noord'] from public.translation_source_revisions
                        where id = :'tp_rev1'), 'TP740-1 rewizja oferty niesie nazwę firmy');
begin;
select pg_temp.assert((select bool_and(protected_terms = array['Logistiek Noord']) and count(*) = 3
                         from public.claim_translation_jobs(100, 300) where entity_id = :'TPJ1'),
  'TP740-1b claim wydaje nazwy chronione rewizji dla każdego języka docelowego');
rollback;

-- TP740-2: zmiana nazwy firmy (bez zmiany treści oferty) = nowa rewizja z nową nazwą; zadania
-- starej rewizji superseded.
update public.companies set name = 'Logistiek Noord BV' where id = :'TPCO';
select pg_temp.assert((select current_revision_no from public.translation_sources where entity_id = :'TPJ1') = 2
  and (select protected_terms = array['Logistiek Noord BV'] from public.translation_source_revisions
        where entity_id = :'TPJ1' and revision_no = 2)
  and (select fields::text from public.translation_source_revisions where entity_id = :'TPJ1' and revision_no = 2) = :'tp_f1'
  and not exists (select 1 from public.translation_jobs where revision_id = :'tp_rev1' and status in ('queued', 'retry', 'leased'))
  and (select count(*) from public.translation_jobs j join public.translation_source_revisions r on r.id = j.revision_id
        where r.entity_id = :'TPJ1' and r.revision_no = 2 and j.status = 'queued') = 3,
  'TP740-2 zmiana nazwy firmy = nowa rewizja (te same pola), stare zadania superseded');

-- TP740-2N (kontrola ujemna): odcisk liczony jak w 0145 (bez nazw) jest identyczny dla obu
-- rewizji — bez nazw w odcisku zmiana nazwy byłaby „unchanged”.
select pg_temp.assert(
  encode(sha256(convert_to('nl' || E'\n' || (:'tp_f1')::jsonb::text, 'UTF8')), 'hex')
    = encode(sha256(convert_to('nl' || E'\n' || (select fields::text from public.translation_source_revisions
                                                   where entity_id = :'TPJ1' and revision_no = 2)::jsonb::text, 'UTF8')), 'hex')
  and (select content_hash from public.translation_source_revisions where entity_id = :'TPJ1' and revision_no = 2) <> :'tp_hash1',
  'TP740-2N kontrola ujemna: odcisk bez nazw nie odróżnia zmiany nazwy firmy');

-- TP740-2Nb (kontrola ujemna): trigger firmy z 0146 (bez `name`) nie reaguje na zmianę nazwy.
begin;
drop trigger trg_job_translation_sync_companies on public.companies;
create constraint trigger trg_job_translation_sync_companies
  after update of status, deleted_at on public.companies deferrable initially deferred
  for each row execute function public.trg_job_translation_sync();
update public.companies set name = 'Northern Logistics' where id = :'TPCO';
set constraints all immediate;
select pg_temp.assert((select current_revision_no from public.translation_sources where entity_id = :'TPJ1') = 2,
  'TP740-2Nb kontrola ujemna: bez `name` w triggerze zmiana nazwy nie tworzy rewizji');
rollback;
begin;
update public.companies set name = 'Northern Logistics' where id = :'TPCO';
set constraints all immediate;
select pg_temp.assert((select current_revision_no from public.translation_sources where entity_id = :'TPJ1') = 3,
  'TP740-2Nc z triggerem 0190 ta sama zmiana tworzy rewizję');
rollback;

-- TP740-3: normalizacja — kolejność, spacje, duplikaty i puste nie zmieniają rewizji; inna nazwa
-- przy tej samej treści = nowa rewizja; bez nazw (5/6 argumentów) jak w 0145.
-- TPE1 = szkic (od 0223 źródło wymaga istniejącej encji, #754).
insert into public.jobs(id, company_id, slug, title, category, contract_type, city, region, status, default_locale)
  values (:'TPE1', :'TPCO', 'draft-tp740-e1', 'Magazynier', 'warehouse', 'permanent', 'Gent', 'Vlaanderen', 'draft', 'pl');
set role service_role;
select pg_temp.assert(((public.record_translation_source('job', :'TPE1'::uuid, 'pl', '{"title":"Magazynier"}'::jsonb,
    'tr-v1', 0, array[' Beta ', 'Alfa', 'Alfa', '', null]))->>'status') = 'created', 'TP740-3 rewizja z nazwami');
select pg_temp.assert((select protected_terms = array['Alfa', 'Beta'] from public.translation_source_revisions
                        where entity_id = :'TPE1' and revision_no = 1), 'TP740-3b nazwy znormalizowane i posortowane');
select pg_temp.assert(((public.record_translation_source('job', :'TPE1'::uuid, 'pl', '{"title":"Magazynier"}'::jsonb,
    'tr-v1', 0, array['Beta', 'Alfa']))->>'status') = 'unchanged', 'TP740-3c ta sama lista w innej kolejności = unchanged');
select pg_temp.assert(((public.record_translation_source('job', :'TPE1'::uuid, 'pl', '{"title":"Magazynier"}'::jsonb,
    'tr-v1', 0, array['Gamma']))->>'status') = 'created', 'TP740-3d inna nazwa = nowa rewizja');
select pg_temp.assert(((public.record_translation_source('job', :'TPE1'::uuid, 'pl', '{"title":"Magazynier"}'::jsonb,
    'tr-v1'))->>'status') = 'created', 'TP740-3e bez nazw (5 argumentów) = nowa rewizja');
select pg_temp.assert((select protected_terms = '{}'::text[] from public.translation_source_revisions where entity_id = :'TPE1' and revision_no = 3)
  and (select content_hash from public.translation_source_revisions where entity_id = :'TPE1' and revision_no = 3)
      = encode(sha256(convert_to('pl' || E'\n' || '{"title": "Magazynier"}'::jsonb::text, 'UTF8')), 'hex'),
  'TP740-3f bez nazw: pusta lista, odcisk jak w 0145');

-- TP740-4: limity — najwyżej 10 nazw, każda ≤ 200 znaków, bez znaków sterujących.
select pg_temp.expect_error(format($$select public.record_translation_source('job', %L, 'pl', '{"title":"X"}'::jsonb, 'tr-v1', 0,
