-- CT61-7: limit 3 wiadomości / adres / 24 h (nowe klucze).
set role service_role;
select count(*) from public.submit_contact_message(null, gen_random_uuid(), 'other', :'CTMSG', null, 'kontakt@test.be', 'pl');
select count(*) from public.submit_contact_message(null, gen_random_uuid(), 'other', :'CTMSG', null, 'kontakt@test.be', 'pl');
