select pg_temp.assert(
  exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'idx_applications_company_submitted')
  and exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'idx_jobs_company_created'),
  'EP05-6b indeksy kursora zgłoszeń i ofert istnieją');

-- Sprzątanie EP05.
drop table ep_all;
delete from public.jobs where company_id in (:'EPC', :'EPD');
delete from public.companies where id in (:'EPC', :'EPD');
delete from auth.users where id in (:'EPO', :'EPM', :'EPX', :'EPNEW')
  or id in (select format('e9c20000-0000-0000-0000-000000000%s', 100 + n)::uuid from generate_series(1, 25) n);

-- ============================================================================
-- AC155. Edytor rewizji kampanii e-mail (#45, 0155): admin_create_email_campaign_revision —
--        tylko admin (is_admin), idempotencja po kluczu klienta (retry = ta sama rewizja),
--        komplet języków i treść, którą worker wyrenderuje, nowa rewizja = szkic,
--        audyt `email_campaign.revision_created` bez treści.
-- ============================================================================
\set AC155K1 'a2020000-0000-4000-8000-000000000001'
\set AC155K2 'a2020000-0000-4000-8000-000000000002'
reset role; reset app.current_uid;

-- AC155-1: anon bez EXECUTE; kandydat i pracodawca → PERMISSION_DENIED, bez wiersza.
set role anon; reset app.current_uid; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-news'', %L::jsonb)',
  :'AC155K1', :'CMJOBS'), 'permission denied', 'AC155-1 anon nie wywoła edytora');
reset role;
set role authenticated; set app.current_uid = :'CANDA'; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-news'', %L::jsonb)',
  :'AC155K1', :'CMJOBS'), 'PERMISSION_DENIED', 'AC155-1b kandydat nie tworzy rewizji');
select pg_temp.expect_error(format('select public.create_email_campaign_revision(''ac155-news'', %L::jsonb)', :'CMJOBS'),
  'permission denied', 'AC155-1c kandydat nie wywoła RPC service_role z 0101');
reset role; reset app.current_uid;
set role authenticated; set app.current_uid = :'EMPA'; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-news'', %L::jsonb)',
  :'AC155K1', :'CMJOBS'), 'PERMISSION_DENIED', 'AC155-1d pracodawca nie tworzy rewizji');
reset role; reset app.current_uid;
select pg_temp.assert(not exists (select 1 from public.email_campaigns where slug = 'ac155-news'),
  'AC155-1e odmowy nie utworzyły rewizji');

-- AC155-2: admin tworzy szkic; ponowienie tym samym kluczem = ta sama rewizja (bez duplikatu);
--          ten sam klucz z innym slugiem → VALIDATION_FAILED; nowy klucz = kolejna rewizja.
set role authenticated; set app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_create_email_campaign_revision(:'AC155K1', 'ac155-news', :'CMJOBS'::jsonb) as ac155_rev1 \gset
select public.admin_create_email_campaign_revision(:'AC155K1', 'ac155-news', :'CMJOBS'::jsonb) as ac155_retry \gset
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-other'', %L::jsonb)',
  :'AC155K1', :'CMJOBS'), 'VALIDATION_FAILED', 'AC155-2 ten sam klucz z innym slugiem odrzucony');
select public.admin_create_email_campaign_revision(:'AC155K2', 'ac155-news', :'CMJOBS'::jsonb) as ac155_rev2 \gset
reset role; reset app.current_uid;
select pg_temp.assert(:'ac155_rev1' = :'ac155_retry', 'AC155-2b ponowienie tym samym kluczem zwraca tę samą rewizję');
select pg_temp.assert(
  (select string_agg(revision || ':' || status, ',' order by revision) from public.email_campaigns
    where slug = 'ac155-news') = '1:draft,2:draft'
  and not exists (select 1 from public.email_campaigns where slug = 'ac155-other')
  and (select client_key from public.email_campaigns where id = :'ac155_rev1') = :'AC155K1'::uuid,
  'AC155-2c dwie rewizje (szkice, bez duplikatu), klucz zapisany przy rewizji');

-- AC155-3: audyt — po jednym wpisie na rewizję (ponowienie bez wpisu), aktor = admin,
--          tylko status/slug/rewizja, bez treści.
select pg_temp.assert(
  (select count(*) = 2
          and bool_and(actor_id = :'ADMIN'::uuid and entity_type = 'email_campaign' and before_data is null
                       and after_data ->> 'status' = 'draft' and after_data ->> 'slug' = 'ac155-news'
                       and (after_data - 'status' - 'slug' - 'revision') = '{}'::jsonb
                       and not (after_data::text like '%Magazynier%'))
     from public.audit_logs
    where action = 'email_campaign.revision_created'
      and entity_id in (:'ac155_rev1'::uuid, :'ac155_rev2'::uuid)),
  'AC155-3 audyt: jeden wpis na rewizję, admin, bez treści');

-- AC155-4: treść, której worker nie wyrenderuje, i brak języka → VALIDATION_FAILED, bez zapisu.
set role authenticated; set app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-bad'', (%L::jsonb - ''en''))',
  gen_random_uuid(), :'CMJOBS'), 'VALIDATION_FAILED', 'AC155-4 brak języka (en) odrzucony');
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-bad'', jsonb_set(%L::jsonb, ''{pl,jobs,0,isDemo}'', ''true''))',
  gen_random_uuid(), :'CMJOBS'), 'VALIDATION_FAILED', 'AC155-4b oferta demonstracyjna odrzucona');
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-bad'', jsonb_set(%L::jsonb, ''{fr,jobs,0,locale}'', ''"pl"''))',
  gen_random_uuid(), :'CMJOBS'), 'VALIDATION_FAILED', 'AC155-4c język oferty ≠ język wpisu odrzucony');
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-bad'', jsonb_set(%L::jsonb, ''{nl,jobs,0,title}'', ''"Hej {{imie}}"''))',
  gen_random_uuid(), :'CMJOBS'), 'VALIDATION_FAILED', 'AC155-4d placeholder odrzucony');
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''ac155-bad'', jsonb_set(%L::jsonb, ''{en,jobs,0,city}'', ''"  "''))',
  gen_random_uuid(), :'CMJOBS'), 'VALIDATION_FAILED', 'AC155-4e puste miasto odrzucone');
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(%L, ''Zły Slug'', %L::jsonb)',
  gen_random_uuid(), :'CMJOBS'), 'VALIDATION_FAILED: slug', 'AC155-4f zły slug kampanii odrzucony');
select pg_temp.expect_error(format('select public.admin_create_email_campaign_revision(null, ''ac155-bad'', %L::jsonb)',
  :'CMJOBS'), 'VALIDATION_FAILED', 'AC155-4g brak klucza odrzucony');
reset role; reset app.current_uid;
select pg_temp.assert(
  not exists (select 1 from public.email_campaigns where slug in ('ac155-bad', 'Zły Slug'))
  and not exists (select 1 from public.audit_logs where action = 'email_campaign.revision_created'
                   and after_data ->> 'slug' = 'ac155-bad'),
  'AC155-4h odrzucenia bez rewizji i bez audytu');

-- AC155-5: nowa rewizja nie jest aktywowana — aktywacja to osobny krok (0111).
select pg_temp.assert(
  (select activated_at is null from public.email_campaigns where id = :'ac155_rev2'),
  'AC155-5 nowa rewizja bez aktywacji');
set role authenticated; set app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_activate_email_campaign(:'ac155_rev2', 'draft');
reset role; reset app.current_uid;
select pg_temp.assert(
  (select status from public.email_campaigns where id = :'ac155_rev2') = 'active'
  and (select status from public.email_campaigns where id = :'ac155_rev1') = 'superseded',
  'AC155-5b aktywacja osobnym krokiem działa na rewizji z edytora');

-- AC155-6: KONTROLA UJEMNA — wariant bez idempotencji (samo opakowanie 0101) przy ponowieniu
--          tworzy duplikat (asercje AC155-2b/2c wykrywają brak klucza).
begin;
create or replace function public.admin_create_email_campaign_revision(p_client_key uuid, p_slug text, p_content jsonb)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then raise exception 'PERMISSION_DENIED' using errcode = '42501'; end if;
  return public.create_email_campaign_revision(p_slug, p_content);
end $$;
set local role authenticated; set local app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_create_email_campaign_revision(:'AC155K1', 'ac155-neg', :'CMJOBS'::jsonb) as ac155_neg1 \gset
select public.admin_create_email_campaign_revision(:'AC155K1', 'ac155-neg', :'CMJOBS'::jsonb) as ac155_neg2 \gset
reset role;
select pg_temp.assert(:'ac155_neg1' <> :'ac155_neg2'
  and (select count(*) from public.email_campaigns where slug = 'ac155-neg') = 2,
  'AC155-6 bez idempotencji ponowienie tworzy duplikat — test wykrywa błąd');
rollback;
reset role; reset app.current_uid;

-- AC155-7: KONTROLA UJEMNA — bez reguł workera (tylko kontrola kształtu z 0101) rewizja
--          z ofertą demonstracyjną przeszłaby (asercja AC155-4b wykrywa brak reguł).
begin;
create or replace function public.email_campaign_jobs_renderable(p_content jsonb)
returns boolean language sql immutable as $$ select true $$;
set local role authenticated; set local app.current_uid = :'ADMIN'; select pg_temp.assert_client_role();
select public.admin_create_email_campaign_revision(gen_random_uuid(), 'ac155-neg-demo',
  jsonb_set(:'CMJOBS'::jsonb, '{pl,jobs,0,isDemo}', 'true'));
reset role;
select pg_temp.assert(exists (select 1 from public.email_campaigns where slug = 'ac155-neg-demo'),
  'AC155-7 bez reguł workera oferta demo trafia do rewizji — test wykrywa błąd');
rollback;
reset role; reset app.current_uid;

-- ============================================================================
-- MP03. Materializacja dopasowań (P1-03, 0147): triggery kolejkują podmioty, worker
-- (service_role) pobiera wejścia tylko dla par kwalifikujących się i zapisuje wynik
-- `match_recompute_apply`, które sprawdza KAŻDĄ parę ponownie w bazie: profil ukończony
-- i wyszukiwalny (#494), 18+ (#492), bez blokady firmy (#97), oferta aktywna firmy verified.
-- Kontrole ujemne: kwalifikacja bez warunku widoczności / wieku / blokady / verified oraz
-- zapis bez ponownej kontroli par dają wiersz, którego nie powinno być.
-- Cała sekcja w transakcji cofanej (kolejka i wiersze nie wpływają na inne sekcje).
-- ============================================================================
\echo '--- MP03 materializacja matches (0147) ---'
\set MPC  'e1903000-0000-0000-0000-000000000001'
\set MPH  'e1903000-0000-0000-0000-000000000002'
\set MPM  'e1903000-0000-0000-0000-000000000003'
\set MPE  'e1903000-0000-0000-0000-000000000004'
\set MPF1 'e1903000-0000-0000-0000-0000000000f1'
\set MPF2 'e1903000-0000-0000-0000-0000000000f2'
\set MPFU 'e1903000-0000-0000-0000-0000000000f3'
\set MPJ1 'e1903000-0000-0000-0000-0000000000a1'
\set MPJ2 'e1903000-0000-0000-0000-0000000000a2'
\set MPJU 'e1903000-0000-0000-0000-0000000000a3'
\set MPJD 'e1903000-0000-0000-0000-0000000000a4'
begin;
insert into auth.users(id,email,name,raw_user_meta_data) values
  (:'MPC','mpc@test.be','Mp C','{"role":"candidate","first_name":"Mia","last_name":"Match","locale":"pl"}'),
  (:'MPH','mph@test.be','Mp H','{"role":"candidate","first_name":"Hugo","last_name":"Hidden","locale":"nl"}'),
  (:'MPM','mpm@test.be','Mp M','{"role":"candidate","first_name":"Mila","last_name":"Minor","locale":"fr"}'),
  (:'MPE','mpe@test.be','Mp E','{"role":"employer","first_name":"Rek","last_name":"Mp","locale":"en"}');
-- MPM deklaruje przedział 16–17 (przed fixture, który dopisuje 18+ pozostałym).
insert into public.candidate_age_attestations (profile_id, min_age, source) values (:'MPM', 16, 'signup');
select test_fixture.attest_candidates();
insert into public.companies(id,name,status) values
  (:'MPF1','Firma Mp 1','verified'), (:'MPF2','Firma Mp 2','verified'), (:'MPFU','Firma Mp U','unverified');
insert into public.company_members(company_id,profile_id,role,is_active) values (:'MPF1',:'MPE','owner',true);
delete from public.match_recompute_queue;

-- MP1: publikacja oferty (insert active) i szkic.
insert into public.jobs(id,company_id,slug,title,category,contract_type,city,region,status,default_locale,occupation,published_at) values
  (:'MPJ1',:'MPF1','job-mp-1','Magazynier MP','warehouse','permanent','Antwerpia','Flandria','active','pl','magazynier', now()),
  (:'MPJ2',:'MPF2','job-mp-2','Magazynier MP2','warehouse','permanent','Antwerpia','Flandria','active','pl','magazynier', now()),
  (:'MPJU',:'MPFU','job-mp-u','Magazynier MPU','warehouse','permanent','Antwerpia','Flandria','active','pl','magazynier', now()),
  (:'MPJD',:'MPF1','job-mp-d','Szkic MP','warehouse','permanent','Antwerpia','Flandria','draft','pl','magazynier', null);
select pg_temp.assert(
  (select count(*) from public.match_recompute_queue where kind = 'job' and subject_id in (:'MPJ1', :'MPJ2', :'MPJU')) = 3
  and not exists (select 1 from public.match_recompute_queue where subject_id = :'MPJD'),
  'MP1 aktywna oferta trafia do kolejki, szkic nie');

-- Profile: MPC kwalifikuje się; MPH ukończony, ale niewyszukiwalny; MPM 16–17 (wyszukiwalny
-- tylko z pominięciem triggera wieku — stan, którego 0126 nie dopuszcza, dla kontroli bazy).
insert into public.candidate_profiles(profile_id, is_searchable, profile_completed, occupations, categories, city, region, availability)
values (:'MPC', true, true, array['magazynier'], array['warehouse']::public.job_category[], 'Antwerpia', 'Flandria', 'immediate'),
       (:'MPH', false, true, array['magazynier'], array['warehouse']::public.job_category[], 'Antwerpia', 'Flandria', 'immediate');
set local session_replication_role = replica;
insert into public.candidate_profiles(profile_id, is_searchable, profile_completed, occupations, categories, city, region, availability)
values (:'MPM', true, true, array['magazynier'], array['warehouse']::public.job_category[], 'Antwerpia', 'Flandria', 'immediate');
set local session_replication_role = origin;
insert into public.candidate_skills(candidate_profile_id, skill_label)
  select id, 'wózek widłowy' from public.candidate_profiles where profile_id = :'MPC';
insert into public.candidate_company_blocks(candidate_id, company_id) values (:'MPC', :'MPF2');
select pg_temp.assert(
  (select count(*) from public.match_recompute_queue where kind = 'candidate' and subject_id in (:'MPC', :'MPH')) = 2,
  'MP1b zmiana profilu/relacji/blokady kolejkuje kandydata (jeden wiersz na podmiot)');
select pg_temp.assert(
  (select version from public.match_recompute_queue where kind = 'candidate' and subject_id = :'MPC') >= 3,
  'MP1c kolejne zgłoszenia podbijają wersję zamiast dublować wiersz');

-- MP2: kwalifikacja w bazie.
select pg_temp.assert(public.match_pair_eligible(:'MPC', :'MPJ1'), 'MP2 kandydat wyszukiwalny 18+ × oferta verified');
select pg_temp.assert(not public.match_pair_eligible(:'MPH', :'MPJ1'), 'MP2b niewyszukiwalny profil (#494) → brak pary');
select pg_temp.assert(not public.match_pair_eligible(:'MPM', :'MPJ1'), 'MP2c kandydat 16–17 (#492) → brak pary');
select pg_temp.assert(not public.match_pair_eligible(:'MPC', :'MPJ2'), 'MP2d blokada firmy (#97) → brak pary');
select pg_temp.assert(not public.match_pair_eligible(:'MPC', :'MPJU'), 'MP2e firma niezweryfikowana → brak pary');
select pg_temp.assert(not public.match_pair_eligible(:'MPC', :'MPJD'), 'MP2f szkic → brak pary');

-- MP3: wejścia dla kandydata = tylko oferty kwalifikujące się; bez imienia i kontaktu.
set role service_role;
select pg_temp.assert(
  (select (i ->> 'eligible')::boolean
      and jsonb_array_length(i -> 'candidates') = 1
      and (select array_agg(j ->> 'job_id') from jsonb_array_elements(i -> 'jobs') j) @> array[:'MPJ1']
      and not (i -> 'jobs')::text like '%' || :'MPJ2' || '%'
      and not (i -> 'jobs')::text like '%' || :'MPJU' || '%'
      and (i -> 'candidates' -> 0 -> 'skills') @> '[{"skill_label":"wózek widłowy"}]'
      and not (i::text ~* 'mpc@test|Mia|Match')
   from (select public.match_recompute_inputs('candidate', :'MPC'::uuid, 500) i) x),
  'MP3 inputs kandydata: tylko pary kwalifikujące się, dane zawodowe bez PII');
select pg_temp.assert(
  (select (public.match_recompute_inputs('candidate', :'MPH'::uuid, 500) ->> 'eligible')::boolean) is false
  and (select (public.match_recompute_inputs('candidate', :'MPM'::uuid, 500) ->> 'eligible')::boolean) is false
  and (select (public.match_recompute_inputs('job', :'MPJU'::uuid, 500) ->> 'eligible')::boolean) is false,
  'MP3b niewidoczny / 16–17 / oferta firmy niezweryfikowanej → eligible=false');
select pg_temp.assert(
  (select not (i -> 'candidates')::text like '%' || :'MPH' || '%'
      and not (i -> 'candidates')::text like '%' || :'MPM' || '%'
   from (select public.match_recompute_inputs('job', :'MPJ1'::uuid, 1000) i) x),
  'MP3c inputs oferty nie zawierają niewidocznego ani niepełnoletniego kandydata');

-- MP4: apply ponownie kwalifikuje każdą parę — worker podający niedozwolone pary nic nie zapisze.
select pg_temp.assert(
  (select r = '{"upserted": 1, "skipped": 2, "deleted": 0}'::jsonb
   from public.match_recompute_apply('candidate', :'MPC'::uuid, 0,
     jsonb_build_array(:'MPJ1', :'MPJ2', :'MPJU'),
     jsonb_build_array(
       jsonb_build_object('other_id', :'MPJ1', 'score', 81, 'matched', jsonb_build_array('magazynier'),
                          'missing', '[]'::jsonb, 'strengths', '[]'::jsonb, 'mandatory_met', 0,
                          'mandatory_total', 0, 'summary_key', 'good'),
       jsonb_build_object('other_id', :'MPJ2', 'score', 81, 'summary_key', 'good'),
       jsonb_build_object('other_id', :'MPJU', 'score', 81, 'summary_key', 'good'))) r),
  'MP4 apply: zapis tylko pary kwalifikującej się (blokada i firma niezweryfikowana pominięte)');
select pg_temp.assert(
  (select count(*) from public.matches where candidate_id = :'MPC') = 1
  and (select score = 81 and summary_key = 'good' and matched = array['magazynier'] and not is_demo
       from public.matches where candidate_id = :'MPC' and job_id = :'MPJ1'),
  'MP4b wiersz z wynikiem workera');
select pg_temp.assert(
  (select count(*) from public.matches where candidate_id in (:'MPH', :'MPM')) = 0,
  'MP4c brak wierszy niewidocznego i niepełnoletniego');
-- Wersja 0 ≠ bieżąca: podmiot zostaje w kolejce, dzierżawa zwolniona.
select pg_temp.assert(
  (select locked_until is null from public.match_recompute_queue where kind = 'candidate' and subject_id = :'MPC'),
  'MP4d nieaktualna wersja nie zdejmuje podmiotu z kolejki');
select pg_temp.expect_error(format(
  'select public.match_recompute_apply(''job'', %L::uuid, 0, jsonb_build_array(%L), jsonb_build_array(jsonb_build_object(''other_id'', %L, ''score'', 101, ''summary_key'', ''good'')))',
  :'MPJ1', :'MPH', :'MPH'), 'VALIDATION_FAILED', 'MP4e wynik spoza 0–100 odrzucony');
select pg_temp.expect_error(format(
  'select public.match_recompute_apply(''job'', %L::uuid, 0, ''[]''::jsonb, jsonb_build_array(jsonb_build_object(''other_id'', %L, ''score'', 50, ''summary_key'', ''partial'')))',
  :'MPJ1', :'MPC'), 'VALIDATION_FAILED', 'MP4f para spoza rozważonych odrzucona');
reset role;

-- MP5: wiersz sprzed zmiany (np. seed/operator) znika przy przeliczeniu niekwalifikującego się.
insert into public.matches(candidate_id, job_id, score) values (:'MPH', :'MPJ1', 70);
set role service_role;
select pg_temp.assert(
  (select (r ->> 'deleted')::int = 1
   from public.match_recompute_apply('candidate', :'MPH'::uuid,
     (select version from public.match_recompute_queue where kind = 'candidate' and subject_id = :'MPH'),
     '[]'::jsonb, '[]'::jsonb) r),
  'MP5 niewidoczny kandydat: przeliczenie usuwa jego wiersz');
-- Osobne zapytania: migawka instrukcji z apply nie widzi jeszcze jego zmian.
select pg_temp.assert(
  (select count(*) from public.matches where candidate_id = :'MPH') = 0
  and not exists (select 1 from public.match_recompute_queue where kind = 'candidate' and subject_id = :'MPH'),
  'MP5b brak wiersza; podmiot zdjęty z kolejki (bieżąca wersja)');
reset role;

-- MP6: blokada firmy po zapisie → przeliczenie kandydata usuwa wiersz tej firmy.
insert into public.candidate_company_blocks(candidate_id, company_id) values (:'MPC', :'MPF1');
set role service_role;
select pg_temp.assert(
  (select (r ->> 'deleted')::int = 1
   from public.match_recompute_apply('candidate', :'MPC'::uuid, 0, '[]'::jsonb, '[]'::jsonb) r),
  'MP6 blokada firmy (#97): przeliczenie usuwa wiersz jej oferty');
select pg_temp.assert((select count(*) from public.matches where candidate_id = :'MPC') = 0,
  'MP6b brak wiersza dopasowania do oferty zablokowanej firmy');
reset role;
delete from public.candidate_company_blocks where candidate_id = :'MPC' and company_id = :'MPF1';

-- MP7: claim — SKIP LOCKED + dzierżawa; drugi claim nie bierze tych samych podmiotów.
set role service_role;
select coalesce(string_agg(kind || ':' || subject_id, ','), '') as mp_claimed, count(*) as mp_claimed_n
  from public.match_recompute_claim(50) \gset
select pg_temp.assert(:mp_claimed_n > 0, 'MP7 claim zwraca podmioty');
select pg_temp.assert(
  (select locked_until > now() and attempts = 1 from public.match_recompute_queue
    where kind || ':' || subject_id = split_part(:'mp_claimed', ',', 1)),
  'MP7a claim ustawia dzierżawę i licznik prób');
select pg_temp.assert(
  not exists (select 1 from public.match_recompute_claim(50) c
              where c.kind || ':' || c.subject_id = any(string_to_array(:'mp_claimed', ','))),
  'MP7b dzierżawa: drugi claim nie bierze tych samych podmiotów');
select pg_temp.assert((select count(*) from public.match_recompute_claim(1000)) <= 50,
  'MP7c limit claimu ≤ 50');
reset role;

-- MP8: uprawnienia — klient nie ma kolejki ani RPC workera.
select set_config('app.current_uid', :'MPE', false);
set role authenticated; select pg_temp.assert_client_role();
select pg_temp.expect_error('select count(*) from public.match_recompute_queue', 'permission denied', 'MP8 authenticated nie czyta kolejki');
select pg_temp.expect_error('select * from public.match_recompute_claim(1)', 'permission denied', 'MP8b authenticated nie woła claim');
select pg_temp.expect_error(format('select public.match_recompute_inputs(''candidate'', %L::uuid, 1)', :'MPC'),
  'permission denied', 'MP8c authenticated nie czyta wejść (profil kandydata)');
select pg_temp.expect_error(format('select public.match_recompute_apply(''candidate'', %L::uuid, 0, ''[]''::jsonb, ''[]''::jsonb)', :'MPC'),
  'permission denied', 'MP8d authenticated nie zapisuje dopasowań');
select pg_temp.expect_error(format('insert into public.matches(candidate_id, job_id, score) values (%L, %L, 99)', :'MPC', :'MPJ1'),
  'permission denied', 'MP8e bezpośredni INSERT do matches odrzucony');
reset role;
set role anon; reset app.current_uid; select pg_temp.assert_client_role();
select pg_temp.expect_error('select * from public.match_recompute_claim(1)', 'permission denied', 'MP8f anon nie woła claim');
reset role;

-- MP9 (kontrole ujemne): osłabiona kwalifikacja przepuszcza pary, których nie powinno być.
savepoint mp_neg;
create or replace function public.match_candidate_eligible(p_candidate uuid)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from public.candidate_profiles cp where cp.profile_id = p_candidate
                 and cp.deleted_at is null and cp.profile_completed);
$$;
select pg_temp.assert(public.match_pair_eligible(:'MPH', :'MPJ1') and public.match_pair_eligible(:'MPM', :'MPJ1'),
  'MP9-N1 bez warunku widoczności i wieku para niewidocznego / 16–17 przeszłaby — MP2b/MP2c to wykrywają');
rollback to savepoint mp_neg;
create or replace function public.match_pair_eligible(p_candidate uuid, p_job uuid)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  select public.match_candidate_eligible(p_candidate) and exists (
    select 1 from public.jobs j where j.id = p_job and j.status = 'active');
$$;
select pg_temp.assert(public.match_pair_eligible(:'MPC', :'MPJ2') and public.match_pair_eligible(:'MPC', :'MPJU'),
  'MP9-N2 bez blokady i verified para przeszłaby — MP2d/MP2e to wykrywają');
rollback to savepoint mp_neg;
-- Zapis bez ponownej kontroli par (naiwny upsert) zostawiłby wiersz firmy zablokowanej.
insert into public.matches(candidate_id, job_id, score) values (:'MPC', :'MPJ2', 81);
select pg_temp.assert((select count(*) from public.matches where candidate_id = :'MPC' and job_id = :'MPJ2') = 1,
  'MP9-N3 naiwny zapis tworzy wiersz zablokowanej firmy — apply (MP4) go pomija');
set role service_role;
select pg_temp.assert(
  (select (r ->> 'deleted')::int >= 1
   from public.match_recompute_apply('candidate', :'MPC'::uuid, 0, '[]'::jsonb, '[]'::jsonb) r),
  'MP9b przeliczenie sprząta wiersz zablokowanej firmy');
select pg_temp.assert((select count(*) from public.matches where candidate_id = :'MPC' and job_id = :'MPJ2') = 0,
  'MP9c wiersz zablokowanej firmy usunięty');
reset role;
release savepoint mp_neg;
rollback;
reset role; reset app.current_uid;

-- ============================================================================
-- MQ233. Kolejka dopasowań bez zakleszczeń (0149): równoległe kroki 3 i 5 onboardingu
-- tego samego kandydata. Krok 5 (sesja A) zapisuje relacje — trigger kolejkuje kandydata;
-- w tym czasie krok 3 (sesja B) zmienia profil; potem A zapisuje certyfikaty
-- (ensure_candidate_profile dotyka profilu). Krok 5 rozbity na dwie instrukcje tej samej
-- transakcji (jak wnętrze save_candidate_onboarding_step5), żeby wymusić przeplot.
-- 0149: match_enqueue blokuje wiersz profilu PRZED wierszem kolejki, więc B czeka na A
-- (bez cyklu) i obie sesje kończą się sukcesem. Kontrola ujemna: definicja z 0147
-- (kolejka bez blokady profilu) → `deadlock detected` w jednej z sesji.
-- Fixture'y i podmiana funkcji zatwierdzane w osobnej sesji (jak PP/TI611).
-- ============================================================================
\echo '--- MQ233 kolejka matches: kolejność blokad profil → kolejka ---'
\set MQC  'e2330000-0000-0000-0000-00000000000c'
\set MQC2 'e2330000-0000-0000-0000-00000000000d'
reset role; reset app.current_uid;
select pg_temp.remote_connect('mq_setup');
select dbl.dblink_exec('mq_setup', $fx$
  insert into auth.users(id,email,name,raw_user_meta_data) values
    ('e2330000-0000-0000-0000-00000000000c','mqc@test.be','Mq C',
     '{"role":"candidate","first_name":"Mona","last_name":"Queue","locale":"pl"}'),
    ('e2330000-0000-0000-0000-00000000000d','mqd@test.be','Mq D',
     '{"role":"candidate","first_name":"Max","last_name":"Queue","locale":"nl"}');
  insert into public.candidate_profiles(profile_id, experience_years) values
    ('e2330000-0000-0000-0000-00000000000c', 1), ('e2330000-0000-0000-0000-00000000000d', 1);
$fx$);

-- MQ1: poprawka — obie sesje kończą się sukcesem, B czekała na A.
select pg_temp.remote_begin('mq_a', :'MQC') as mq_pid_a \gset
select pg_temp.remote_begin('mq_b', :'MQC') as mq_pid_b \gset
select t.v as mq_a1 from dbl.dblink('mq_a',
  $q$select 'ok'::text from public.set_candidate_languages('[{"language":"Nederlands","level":"intermediate"},{"language":"English","level":"fluent"}]'::jsonb)$q$)
  as t(v text) \gset
select dbl.dblink_send_query('mq_b',
  $q$select 'ok'::text from public.save_candidate_onboarding_step3(6, array['heftruck', 'orderpicking', 'VCA'])$q$);
select pg_temp.wait_blocked(:mq_pid_b, 'MQ1 krok 3 czeka na krok 5');
select t.v as mq_a2 from dbl.dblink('mq_a',
  $q$select 'ok'::text from public.set_candidate_certificates('["VCA", {"label": "Heftruck", "expires_at": "2030-01-01"}]'::jsonb)$q$)
  as t(v text) \gset
select dbl.dblink_exec('mq_a', 'commit');
select pg_temp.remote_result('mq_b') as mq_b1 \gset
select dbl.dblink_exec('mq_b', 'commit');
select dbl.dblink_disconnect('mq_a'); select dbl.dblink_disconnect('mq_b');
select pg_temp.assert(:'mq_a1' = 'ok' and :'mq_a2' = 'ok' and :'mq_b1' = 'ok',
  'MQ1 równoległe kroki 3 i 5 tego samego kandydata: obie transakcje bez błędu (było: deadlock → INTERNAL)');
select pg_temp.assert(
  (select cp.experience_years = 6
      and (select count(*) from public.candidate_skills s where s.candidate_profile_id = cp.id) = 3
      and (select count(*) from public.candidate_languages l where l.candidate_profile_id = cp.id) = 2
      and (select count(*) from public.candidate_certificates c where c.candidate_profile_id = cp.id) = 2
   from public.candidate_profiles cp where cp.profile_id = :'MQC'),
  'MQ1b oba kroki zapisane w całości');
select pg_temp.assert(
  (select count(*) = 1 and min(version) >= 2 from public.match_recompute_queue
    where kind = 'candidate' and subject_id = :'MQC'),
  'MQ1c semantyka kolejki bez zmian: jeden wiersz na kandydata, kolejne zgłoszenia podbijają wersję');

-- MQ2 (kontrola ujemna): definicja z 0147 — ta sama sekwencja kończy się zakleszczeniem.
select pg_get_functiondef('public.match_enqueue(text,uuid)'::regprocedure) as mq_fixed_def \gset
select dbl.dblink_exec('mq_setup', $fx$
  create or replace function public.match_enqueue(p_kind text, p_subject uuid)
  returns void language sql security definer set search_path = public, pg_temp as $f$
    insert into public.match_recompute_queue as q (kind, subject_id)
    select p_kind, p_subject
    where p_subject is not null and p_kind in ('candidate', 'job')
    on conflict (kind, subject_id) do update
      set version = q.version + 1, attempts = 0, enqueued_at = now();
  $f$;
$fx$);
select pg_temp.remote_begin('mq_a', :'MQC2') as mq_pid_a \gset
select pg_temp.remote_begin('mq_b', :'MQC2') as mq_pid_b \gset
select t.v as mq_n_a1 from dbl.dblink('mq_a',
  $q$select 'ok'::text from public.set_candidate_languages('[{"language":"Nederlands","level":"intermediate"}]'::jsonb)$q$)
  as t(v text) \gset
select dbl.dblink_send_query('mq_b',
  $q$select 'ok'::text from public.save_candidate_onboarding_step3(6, array['heftruck'])$q$);
select pg_temp.wait_blocked(:mq_pid_b, 'MQ2 krok 3 czeka na kolejkę');
select dbl.dblink_send_query('mq_a',
  $q$select 'ok'::text from public.set_candidate_certificates('["VCA"]'::jsonb)$q$);
select pg_temp.remote_result('mq_a') as mq_n_a2 \gset
select pg_temp.remote_result('mq_b') as mq_n_b1 \gset
select dbl.dblink_exec('mq_a', 'rollback'); select dbl.dblink_exec('mq_b', 'rollback');
select dbl.dblink_disconnect('mq_a'); select dbl.dblink_disconnect('mq_b');
-- Przywrócenie definicji z 0149 (zatwierdzone, jak podmiana).
select dbl.dblink_exec('mq_setup', :'mq_fixed_def');
select dbl.dblink_disconnect('mq_setup');
select pg_temp.assert(
  strpos(:'mq_n_a2' || ' ' || :'mq_n_b1', 'deadlock detected') > 0,
  'MQ2-N definicja z 0147: równoległe kroki 3 i 5 → deadlock (MQ1 wykrywa regresję)');
select pg_temp.assert(
  pg_get_functiondef('public.match_enqueue(text,uuid)'::regprocedure) ~ 'for no key update',
  'MQ2b definicja z 0149 przywrócona po kontroli ujemnej');

-- ============================================================================
-- JP12. JobPosting validThrough / unitText (audyt P1-12): get_public_job zwraca
--       expires_at i salary_period oferty — źródło `validThrough` i
--       `baseSalary.value.unitText` w JSON-LD (src/lib/seo/structured-data.ts; mapowanie
--       wiersza to_jsonb → JobDetail w src/lib/jobs.ts). Bez daty = null, bez kwot = brak baseSalary
--       (JSON-LD pomija pole, bez wymyślonej wartości). Kontrola ujemna: definicja bez kolumny
--       w transakcji cofanej → asercja JP12-1 pada.
-- ============================================================================
\set JPCO 'c1120000-0000-0000-0000-0000000000a1'
\echo '--- JP12 get_public_job: expires_at + salary_period ---'
reset role; reset app.current_uid;
insert into public.companies(id,name,status,is_demo) values (:'JPCO','JP12 Sp','verified',false);
insert into public.jobs(id,company_id,slug,title,category,contract_type,city,region,status,default_locale,
                        salary_min,salary_max,currency,salary_period,expires_at) values
  ('c1120000-0000-0000-0000-0000000000b1',:'JPCO','jp12-dated','Magazynier JP12','warehouse','permanent','Gent','Flandria','active','pl',
   15,18,'EUR','hour','2099-10-15 23:59:00+00'),
  ('c1120000-0000-0000-0000-0000000000b2',:'JPCO','jp12-undated','Kierowca JP12','warehouse','permanent','Gent','Flandria','active','pl',
   null,null,'EUR','month',null);

set role anon; select pg_temp.assert_client_role();
-- JP12-1: oferta z terminem i okresem — dokładnie te wartości, także w postaci to_jsonb (jak aplikacja).
select pg_temp.assert(
  (select expires_at = '2099-10-15 23:59:00+00'::timestamptz and salary_period = 'hour'
   from public.get_public_job('jp12-dated', 'pl')),
  'JP12-1 expires_at i salary_period z oferty');
select pg_temp.assert(
  (select (to_jsonb(j)->>'expires_at')::timestamptz = '2099-10-15 23:59:00+00'::timestamptz
      and to_jsonb(j)->>'salary_period' = 'hour'
   from public.get_public_job('jp12-dated', 'pl') j),
  'JP12-1b to_jsonb niesie oba pola (odczyt aplikacji)');
-- JP12-2: brak terminu → null (JSON-LD bez validThrough). Okres jest NOT NULL w jobs; bez kwot
-- JSON-LD i tak nie ma baseSalary (normalizeSalary), więc unitText nie powstaje.
select pg_temp.assert(
  (select expires_at is null and salary_min is null and salary_max is null
   from public.get_public_job('jp12-undated', 'pl')),
  'JP12-2 bez daty → expires_at null, bez kwot');
reset role;

-- JP12-3: kontrola ujemna — definicja bez expires_at (null) daje czerwoną asercję JP12-1.
begin;
do $jp$
declare
  v_def text := pg_get_functiondef('public.get_public_job(text, text)'::regprocedure);
begin
  if position(E'j.expires_at,' in v_def) = 0 then
    raise exception 'ASSERT FAILED: JP12-3 fragment j.expires_at nie występuje w get_public_job';
  end if;
  execute replace(v_def, E'j.expires_at,', E'null::timestamptz as expires_at,');
end $jp$;
select pg_temp.assert(
  (select expires_at is null from public.get_public_job('jp12-dated', 'pl')),
  'JP12-3 mutacja bez expires_at — JP12-1 wykrywa regresję');
rollback;
select pg_temp.assert(
  (select expires_at is not null from public.get_public_job('jp12-dated', 'pl')),
  'JP12-3b po cofnięciu definicja wróciła');
reset role; reset app.current_uid;

