  (:'CANDCX','candcx@test.be','Xara N','{"role":"candidate","first_name":"Xara","last_name":"N","locale":"pl"}'),
  (:'RECCN','reccn@test.be','Remi N','{"role":"employer","first_name":"Remi","last_name":"N","locale":"nl"}');
select test_fixture.attest_candidates();
