  select encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex') $$;
create or replace function pg_temp.ti_nonce() returns text language sql volatile as $$
  select replace(gen_random_uuid()::text, '-', '') $$;

