select public.save_job_draft(:'FTJOB'::uuid, $j${
  "translation": {"description": "Praca w magazynie. Kontakt przez WhatsApp, opłata za szkolenie 50 EUR.",
                  "responsibilities": ["Kompletacja zamówień"]}
}$j$::jsonb);
