       format('update public.%I set %I = %L where job_id = %L', r.tbl, r.col, 'hak', :'WMJD'),
       format('%s UPDATE %s', r.tbl, a.who), true
from (values ('job_skills', 'skill_label'), ('job_languages', 'language_label'), ('job_certificates', 'certificate_label'),
