  and (select count(*) from public.email_pending_events where provider_message_id = 'ew-msg-c') = 1,
  'EW788-N1 kontrola ujemna: bez triggera zdarzenie zostaje nieprzypisane');
rollback;
-- ...a z triggerem to samo przypisanie działa.
